<script lang="ts">
 import {artistResolvers,artistResolutionRoute,personProfileRoute} from './people';
 import {onMount} from 'svelte';import Portrait from './Portrait.svelte';import MediaShelf from './MediaShelf.svelte';import {groupMedia} from './collection';import {groupCard,workCard,type Card} from './experience';import type {Entry,Work,Contributor,Provider} from './types';
 export let provider='';export let id='';export let name='';export let entries:Entry[];export let providers:Provider[]=[];export let token:string;export let open:(c:Card)=>void;
 const localName=name;
 let image='';let imageSource='';let imageCredit='';let imageLicense='';let candidates:Contributor[]=[];
 let resolutionProvider='';let candidateProvider='';
 $: resolvers=artistResolvers(providers);
 $: if(!resolvers.some(p=>p.id===resolutionProvider)){resolutionProvider=resolvers.length===1?resolvers[0].id:'';candidates=[];candidateProvider='';}
 let biography='';let detail='';let works:Work[]=[];let page=1;let pages=1;let busy=false;let error='';let alive=true;const abort=new AbortController();
 $: local=groupMedia(entries.filter(e=>e.kind==='music'&&[e.metadata?.artist,e.metadata?.albumArtist].some(a=>a?.toLocaleLowerCase()===localName.toLocaleLowerCase()))).map(groupCard);
 onMount(()=>{if(id)void load(1);else if(resolutionProvider)void explore();return()=>{alive=false;abort.abort();};});
 async function load(next:number){busy=true;error='';try{const r=await fetch(personProfileRoute(provider,id,next),{signal:abort.signal});const data=await r.json();if(!r.ok)throw new Error(data.error);if(alive){name=data.name;biography=data.biography;detail=data.detail;image=data.image||'';imageSource=data.imageSource||'';imageCredit=data.imageCredit||'';imageLicense=data.imageLicense||'';works=data.works;page=data.page;pages=data.pages;}}catch(e){if(alive)error=e instanceof Error?e.message:'Profil indisponible.';}finally{if(alive)busy=false;}}
 async function choose(person:Contributor){if(!candidateProvider)return;provider=candidateProvider;id=person.id;candidates=[];await load(1);}
 async function explore(){const target=resolvers.find(p=>p.id===resolutionProvider);if(!target||busy)return;busy=true;error='';candidates=[];candidateProvider='';try{const r=await fetch(artistResolutionRoute(target.id),{method:'POST',headers:{'Content-Type':'application/json','X-Mosaune-Token':token},body:JSON.stringify({name:localName}),signal:abort.signal});const data=await r.json();if(!r.ok)throw new Error(data.error);if(!alive||target.id!==resolutionProvider)return;candidateProvider=target.id;candidates=data;const exact=candidates.filter(p=>p.name.toLocaleLowerCase()===localName.toLocaleLowerCase());if(exact.length===1)await choose(exact[0]);}catch(e){if(alive)error=e instanceof Error?e.message:'Identification indisponible.';}finally{if(alive)busy=false;}}
</script>
<article class="person-page"><header class="person-hero"><div class="person-photo"><Portrait {name} {image} large/>{#if imageSource}<a class="photo-credit" href={imageSource} target="_blank" rel="noreferrer">Photo : {imageCredit||'Source du fournisseur'}{imageLicense?` · ${imageLicense}`:''} ↗</a>{/if}</div><div><span class="eyebrow">LES PERSONNES DERRIÈRE VOS MÉDIAS</span><h1>{name}</h1><p>{detail||'Une personne, plusieurs histoires.'}</p>{#if !id}{#if resolvers.length}<label>Fournisseur de profils<select bind:value={resolutionProvider} disabled={busy} onchange={()=>{candidates=[];candidateProvider='';error='';}}><option value="" disabled>Choisir un fournisseur…</option>{#each resolvers as source}<option value={source.id}>{source.name}</option>{/each}</select></label><button class="secondary" disabled={busy||!resolutionProvider} onclick={explore}>Identifier l’artiste</button>{:else}<p>Aucun fournisseur de profils d’artistes n’est disponible. Vos albums locaux restent accessibles.</p>{/if}{/if}</div></header>
{#if candidates.length}<section class="artist-candidates"><h2>De quel artiste s’agit-il ?</h2><p>Choisissez le bon profil pour éviter les homonymes.</p>{#each candidates as candidate}<button class="secondary" disabled={busy} onclick={()=>choose(candidate)}>{candidate.name} {candidate.role?`· ${candidate.role}`:''}</button>{/each}</section>{/if}
{#if biography}<section class="person-biography"><h2>À propos</h2><p>{biography}</p></section>{/if}
{#if busy}<p role="status" class="folder-help">Chargement des projets…</p>{/if}{#if error}<p class="notice" role="alert">{error}</p><button class="secondary" disabled={busy} onclick={()=>id?load(page):explore()}>Réessayer</button>{/if}
{#if local.length}<MediaShelf title="Dans votre collection" cards={local} {open}/>{/if}
{#if works.length}<MediaShelf title="Projets et collaborations" subtitle={!id?'Recherche par nom : des homonymes sont possibles. Ouvrez un album pour vérifier les artistes crédités.':'Projets référencés par le fournisseur.'} cards={works.map(workCard)} {open} grid/>{:else if id&&!busy&&!error}<p>Aucun projet renseigné sur cette page.</p>{/if}
{#if id&&pages>1}<div class="discovery-pagination"><button class="secondary" disabled={busy||page<=1} onclick={()=>load(page-1)}>Précédent</button><span>{page} / {pages}</span><button class="secondary" disabled={busy||page>=pages} onclick={()=>load(page+1)}>Suivant</button></div>{/if}
</article>
